    ///< finalize
    void RingMem::release()
    {
        if (m_initialized)
        {
            m_initialized = false;

            if (m_shrMem)
            {
#ifdef _WIN32
                UnmapViewOfFile(m_shrMem);
                CloseHandle(m_handle);
                m_handle = NULL;
#else /* POSIX / pthreads */
                int32_t shrMemSize = (m_itemSize * m_itemCnt + sizeof(ShrMemCtrl) + RINGMEM_ALLIGNMENT - 1) & (~RINGMEM_ALLIGNMENT - 1);
                munmap(m_shrMem, shrMemSize);
                unlink(m_filepath);
                free(m_filepath);
                m_filepath = NULL;
#endif ///< _WIN32
                m_shrMem = NULL;
                m_dataPool = NULL;
                m_itemSize = 0;
                m_itemCnt = 0;
            }

            if (m_protectRW)
            {
                m_protectRW = false;
                if (m_writeSem)
                {
                    m_writeSem->release();

                    delete m_writeSem;
                    m_writeSem = NULL;
                }

                if (m_readSem)
                {
                    m_readSem->release();

                    delete m_readSem;
                    m_readSem = NULL;
                }
            }

        }
    }

    ///< data read
    bool RingMem::readNext(void* dst, fnRWSharedData callback)
    {
        if (!m_initialized || !callback || !dst)
        {
            return false;
        }

        if (m_protectRW)
        {
            if (!m_readSem->take())
            {
                return false;
            }
        }

        int32_t index = ATOMIC_ADD(&m_shrMem->m_read, 1) % m_itemCnt;
        (*callback)(dst, reinterpret_cast<uint8_t *>(m_dataPool) + index * m_itemSize, m_itemSize);

        if (m_protectRW)
        {
            m_writeSem->give(1);
        }

        return true;
    }
